const BLUE='#2563eb',RED='#dc3545', isColor=c=>typeof c==='string'&&/^#[0-9a-f]{6}$/i.test(c);
function teamColor(id,g=game()){return isColor(team(id)?.color)?team(id).color:g?.away===id?RED:BLUE}
function colorText(c){const n=parseInt(c.slice(1),16);return (((n>>16)&255)*.299+((n>>8)&255)*.587+(n&255)*.114)>155?'#102723':'#ffffff'}
function opposingTeam(g,id){return id===g.home?g.away:g.home}
function keeperValue(g,id){const value=g.keepers?.[id];return ['?','empty'].includes(value)||team(id)?.players.some(p=>p.number===value&&p.isKeeper)?value:'?'}
function keeperLabel(id,value){return value==='empty'?'Leeres Tor':value==='?'?'Unbekannt':value?`#${value} ${playerName(id,value)}`:'Bitte auswählen'}
function playerFlags(p){return [p?.leftHanded?'LH':'',p?.isKeeper?'TW':''].filter(Boolean).map(x=>' · '+x).join('')}
function keeperOptions(id,current){const players=(team(id)?.players||[]).filter(p=>p.isKeeper);return `<option value="?" ${!current||current==='?'?'selected':''}>Torhüter unbekannt</option>${current&&!['?','empty'].includes(current)&&!players.some(p=>p.number===current)?`<option selected disabled value="${esc(current)}">#${esc(current)} (damaliger Torhüter)</option>`:''}${players.map(p=>`<option value="${p.number}" ${current===p.number?'selected':''}>#${p.number} ${esc(p.name)}${p.leftHanded?' · LH':''}</option>`).join('')}<option value="empty" ${current==='empty'?'selected':''}>Leeres Tor</option>`}
teamDialog=function(id){
 const t=team(id);let players=(t?.players||[]).map(p=>({...p}));
 modal(`<form id="team-form"><div class="eyebrow">Mannschaft verwalten</div><h2>${t?'Kader bearbeiten':'Neue Mannschaft'}</h2><label>Mannschaftsname<input name="name" required maxlength="70" value="${esc(t?.name||'')}"></label><div class="formgrid"><label>Mannschaftsfarbe<select name="colorMode" id="color-mode"><option value="auto" ${!isColor(t?.color)?'selected':''}>Automatisch: Heim Blau, Gast Rot</option><option value="custom" ${isColor(t?.color)?'selected':''}>Eigene Farbe</option></select></label><label>Eigene Farbe<input type="color" name="color" id="team-color" value="${isColor(t?.color)?t.color:BLUE}" ${!isColor(t?.color)?'disabled':''}></label></div><p class="muted">LH = Linkshänder · TW = Torhüter. Nur als TW markierte Spieler erscheinen in der Torhüterauswahl.</p><div class="roster-table"><table><thead><tr><th>Nr.</th><th>Name</th><th>LH</th><th>TW</th><th></th></tr></thead><tbody id="roster-rows"></tbody></table></div><button type="button" id="add-player">＋ Spieler</button><details style="margin-top:12px"><summary>Mehrere Spieler einfügen</summary><textarea id="roster-bulk" placeholder="7 Max Beispiel&#10;12 Alex Beispiel" aria-label="Spielerliste einfügen"></textarea><button type="button" id="apply-bulk">Spieler ergänzen</button></details><div class="dialog-actions"><button type="button" data-close>Abbrechen</button><button class="primary">Speichern</button></div></form>`);
 const read=()=>{players=[...document.querySelectorAll('[data-roster-row]')].map(row=>({number:row.querySelector('[data-number]').value.trim(),name:row.querySelector('[data-name]').value.trim(),leftHanded:row.querySelector('[data-lh]').checked,isKeeper:row.querySelector('[data-tw]').checked}))};
 const rows=()=>{$('#roster-rows').innerHTML=players.map((p,i)=>`<tr data-roster-row><td><input data-number inputmode="numeric" required pattern="[0-9]{1,2}" maxlength="2" value="${esc(p.number)}" aria-label="Rückennummer ${i+1}"></td><td><input data-name maxlength="100" value="${esc(p.name)}" aria-label="Name ${i+1}"></td><td><input data-lh type="checkbox" ${p.leftHanded?'checked':''} aria-label="Linkshänder ${i+1}"></td><td><input data-tw type="checkbox" ${p.isKeeper?'checked':''} aria-label="Torhüter ${i+1}"></td><td><button type="button" data-remove-player="${i}" aria-label="Spieler ${i+1} entfernen">×</button></td></tr>`).join('');document.querySelectorAll('[data-remove-player]').forEach(b=>b.onclick=()=>{read();players.splice(Number(b.dataset.removePlayer),1);rows()})};rows();
 $('#add-player').onclick=()=>{read();players.push({number:'',name:'',leftHanded:false,isKeeper:false});rows();$('#roster-rows tr:last-child input').focus()};
 $('#apply-bulk').onclick=()=>{try{read();for(const p of parseRoster($('#roster-bulk').value)){const old=players.find(x=>x.number===p.number);if(old){if(p.name)old.name=p.name}else players.push({...p,leftHanded:false,isKeeper:false})}rows();$('#roster-bulk').value=''}catch(e){toast(e.message)}};
 $('#color-mode').onchange=e=>{$('#team-color').disabled=e.target.value==='auto'};
 $('#team-form').onsubmit=e=>{e.preventDefault();read();const nums=new Set();for(const p of players){if(!/^\d{1,2}$/.test(p.number)){toast('Rückennummern bitte von 0 bis 99 eingeben.');return}p.number=String(Number(p.number));if(nums.has(p.number)){toast('Eine Trikotnummer ist doppelt.');return}nums.add(p.number)}const fd=new FormData(e.target),name=fd.get('name').trim();if(!name)return;players.sort((a,b)=>+a.number-+b.number);const color=fd.get('colorMode')==='custom'?fd.get('color'):null;if(t)Object.assign(t,{name,players,color});else db.teams.push({id:uid(),name,players,color});persist();$('#dialog').close();render()}
};
function parseRoster(text){const players=[];for(const line of text.split('\n').map(l=>l.trim()).filter(Boolean)){const m=line.match(/^(\d{1,2})(?:\s+(.*))?$/);if(!m)throw Error('Bitte jede Zeile mit einer Trikotnummer beginnen.');const number=String(Number(m[1]));if(players.some(p=>p.number===number))throw Error('Eine Trikotnummer ist doppelt.');players.push({number,name:m[2]||''})}return players.sort((a,b)=>+a.number-+b.number)}
const teamsViewBeforeColors=teamsView;
teamsView=function(){return teamsViewBeforeColors().replace('<div class="team-list">','<div class="notice">Ohne eigene Farbe: Heimteam Blau, Gastteam Rot. Eigene Farben bleiben für die Mannschaft gespeichert.</div><button class="primary" id="team-csv" style="margin-bottom:20px">↑ Mannschaften importieren</button><div class="team-list">').replace(/<h2>(.*?)<\/h2><button data-editteam="([^"]+)"/g,(all,name,id)=>`<h2><span class="color-dot" style="background:${isColor(team(id)?.color)?team(id).color:'linear-gradient(90deg, '+BLUE+' 50%, '+RED+' 50%)'}"></span> ${name}</h2><button data-editteam="${id}"`)};
function parseCsv(input){const rows=[];let row=[],cell='',quoted=false;const text=input.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0],delimiter=first.includes(';')?';':first.includes('\t')?'\t':',';for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted)quoted=false;else if(!cell)quoted=true;else throw Error('Ungültige Anführungszeichen in der Datei.')}else if(!quoted&&c===delimiter){row.push(cell.trim());cell=''}else if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Ein Textfeld in der Datei ist nicht geschlossen.');row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows}
function parseTeamCsv(text){const rows=parseCsv(text),header=rows.shift()?.map(s=>s.toLowerCase());if(!header||!['mannschaft','nummer','name'].every(k=>header.includes(k)))throw Error('Benötigte Spalten: Mannschaft;Nummer;Name;Farbe (optional).');const get=(r,k)=>r[header.indexOf(k)]||'', groups=new Map();for(const r of rows){const name=get(r,'mannschaft'),n=get(r,'nummer'),color=get(r,'farbe');if(!name||!/^\d{1,2}$/.test(n))throw Error('Jede Zeile benötigt eine Mannschaft und Nummer (0–99).');if(color&&!isColor(color))throw Error('Farbe bitte als Hexwert angeben, z. B. #2563eb.');const key=name.toLocaleLowerCase('de'),item=groups.get(key)||{name,players:[],color:null};const number=String(Number(n));if(item.players.some(p=>p.number===number))throw Error(`Doppelte Nummer ${number} bei ${name}.`);if(color&&item.color&&color.toLowerCase()!==item.color.toLowerCase())throw Error(`Widersprüchliche Farben bei ${name}.`);if(color)item.color=color;item.players.push({number,name:get(r,'name')});groups.set(key,item)}if(!groups.size)throw Error('Die Datei enthält keine Spieler.');return [...groups.values()]}
function teamImportDialog(){modal(`<div class="eyebrow">Feste Rückennummern übernehmen</div><h2>Mannschaften importieren</h2><p class="muted" style="margin:14px 0;line-height:1.6">CSV-Datei auswählen oder Tabelleninhalt einfügen. Dies ist ein allgemeiner Tabellenimport; ein direkter Handball4all-Abruf ist noch nicht angebunden.</p><p class="muted">Spalten: Mannschaft;Nummer;Name;Farbe (optional)</p><input type="file" id="roster-file" accept=".csv,.tsv,.txt,text/csv" aria-label="Mannschaftsdatei" style="width:100%;margin:12px 0"><textarea id="roster-csv" aria-label="Mannschaftsdaten" placeholder="Mannschaft;Nummer;Name;Farbe&#10;TSV Heim;7;Max Beispiel;#2563eb&#10;TSV Heim;12;Alex Beispiel;#2563eb"></textarea><div id="roster-preview"></div><div class="dialog-actions"><button data-close>Abbrechen</button><button id="roster-template">CSV-Vorlage</button><button class="primary" id="check-roster">Vorschau</button></div>`);$('#roster-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2000000){toast('Bitte eine Datei unter 2 MB wählen.');return}$('#roster-csv').value=await f.text();$('#roster-preview').innerHTML=''};$('#roster-template').onclick=()=>download('mannschaft-vorlage.csv','\uFEFFMannschaft;Nummer;Name;Farbe\r\nTSV Heim;7;Max Beispiel;#2563eb\r\nTSV Heim;12;Alex Beispiel;#2563eb\r\nSV Gast;9;Sam Beispiel;#dc3545','text/csv;charset=utf-8');$('#check-roster').onclick=()=>{try{const groups=parseTeamCsv($('#roster-csv').value);$('#roster-preview').innerHTML=`<div class="notice" style="margin-top:12px">${groups.map(t=>`${esc(t.name)}: ${t.players.length} Spieler`).join('<br>')}<p style="margin-top:8px">Neue Mannschaften werden angelegt. Bei gleichem Mannschaftsnamen werden Spieler über die Nummer ergänzt oder aktualisiert. Bestehende andere Nummern und Spieldaten bleiben erhalten.</p><button class="primary" id="apply-roster" style="margin-top:10px">Import übernehmen</button></div>`;$('#apply-roster').onclick=()=>{for(const incoming of groups){const existing=db.teams.find(t=>t.name.toLocaleLowerCase('de')===incoming.name.toLocaleLowerCase('de'));if(existing){for(const p of incoming.players){const old=existing.players.find(x=>x.number===p.number);if(old){if(p.name)old.name=p.name}else existing.players.push(p)}if(incoming.color)existing.color=incoming.color;existing.players.sort((a,b)=>+a.number-+b.number)}else db.teams.push({...incoming,id:uid()})}persist();$('#dialog').close();render();toast('Mannschaften importiert')}}catch(err){toast(err.message)}};$('#roster-csv').oninput=()=>{$('#roster-preview').innerHTML=''}}
const bindBeforeTeamFeatures=bind;
bind=function(){
 bindBeforeTeamFeatures();if($('#team-csv'))$('#team-csv').onclick=teamImportDialog;
 const g=game();if(tab!=='live'||!g)return;
 const color=teamColor(selectedTeam,g);$('.match-workspace').style.setProperty('--team-color',color);$('.match-workspace').style.setProperty('--team-ink',colorText(color));
 document.querySelectorAll('[data-team]').forEach(b=>{const c=teamColor(b.dataset.team,g);b.style.setProperty('--button-team',c);b.style.setProperty('--button-ink',colorText(c))});
 const opponent=opposingTeam(g,selectedTeam),current=editId&&Object.hasOwn(draft,'keeper')?draft.keeper:keeperValue(g,opponent);
 $('.roster-edit').insertAdjacentHTML('beforebegin',`<label class="keeper-picker">Torhüter · ${esc(teamName(opponent))}<select id="opponent-keeper" aria-label="Torhüter der gegnerischen Mannschaft">${keeperOptions(opponent,current)}</select></label>`);
 $('#opponent-keeper').onchange=e=>{if(editId)draft.keeper=e.target.value;else{g.keepers??={};g.keepers[opponent]=e.target.value;persist()}render()};
};
actions.period=()=>{stopClock();game().period=game().period===2?1:2;elapsed=game().period===2?(game().halfMinutes||30)*60:0;game().elapsed=elapsed;persist();render()};
const analysisBeforeKeepers=analysisView;
analysisView=function(){const shots=filtered().filter(s=>s.keeperTeam&&s.keeper&&!['?','empty'].includes(s.keeper));const keys=[...new Set(shots.map(s=>s.keeperTeam+'|'+s.keeper))];return analysisBeforeKeepers()+originAnalysis()+eventAnalysis()+`<div class="card"><h2>Torhüter in dieser Auswahl</h2><p class="muted" style="margin:12px 0">Fangquote = gehalten / (gehalten + Tore). Würfe daneben und Ereignisse ohne Wurf werden dafür nicht gezählt.</p><div class="tablewrap"><table><thead><tr><th>Mannschaft</th><th>Torhüter</th><th>Gehalten</th><th>Gegentore</th><th>Fangquote</th></tr></thead><tbody>${keys.map(key=>{const [tid,n]=key.split('|'),a=shots.filter(s=>s.keeperTeam===tid&&s.keeper===n),saved=a.filter(s=>s.result==='Gehalten').length,goals=a.filter(s=>s.result==='Tor').length;return `<tr><td>${esc(teamName(tid))}</td><td>#${esc(n)} ${esc(a[0].keeperName||playerName(tid,n))}</td><td>${saved}</td><td>${goals}</td><td>${saved+goals?Math.round(saved/(saved+goals)*100)+' %':'–'}</td></tr>`}).join('')||'<tr><td colspan="5">Noch keine Würfe mit bekanntem Torhüter erfasst.</td></tr>'}</tbody></table></div></div>`};
function originAnalysis(){const shots=filtered();return `<div class="card"><h2>Feldsegmente</h2><div class="tablewrap"><table><thead><tr><th>Wurfposition</th><th>Würfe</th><th>Tore</th></tr></thead><tbody>${origins.map(origin=>{const a=shots.filter(s=>s.origin===origin);return `<tr><td>${origin}</td><td>${a.length}</td><td>${a.filter(s=>s.result==='Tor').length}</td></tr>`}).join('')}</tbody></table></div></div>`}
function eventAnalysis(){const events=db.games.filter(g=>!filter.game||g.id===filter.game).flatMap(g=>g.events||[]).filter(e=>(!filter.team||e.team===filter.team)&&(!filter.player||e.player===filter.player));return `<div class="card"><h2>Ereignisse ohne Wurf</h2><p class="muted" style="margin:12px 0">${events.filter(e=>e.result==='Technischer Fehler').length} technische Fehler · ${events.filter(e=>e.result==='Ballverlust').length} Ballverluste. Diese Ereignisse zählen nicht als Würfe.</p><div class="tablewrap"><table><thead><tr><th>Zeit</th><th>Mannschaft</th><th>Spieler</th><th>Ereignis</th></tr></thead><tbody>${events.map(e=>`<tr><td>${esc(e.time)}</td><td>${esc(teamName(e.team))}</td><td>#${esc(e.player)} ${esc(playerName(e.team,e.player))}${(e.leftHanded??team(e.team)?.players.find(p=>p.number===e.player)?.leftHanded)?' · LH':''}${(e.playerIsKeeper??team(e.team)?.players.find(p=>p.number===e.player)?.isKeeper)?' · TW':''}</td><td>${esc(e.result)}</td></tr>`).join('')||'<tr><td colspan="4">Noch keine Ereignisse für diese Auswahl.</td></tr>'}</tbody></table></div></div>`}
render();
